/// Empty or whitespace-only keys and CR/LF/NUL are rejected at every
/// location; RFC 7230 §3.2.6 also rejects anything outside printable ASCII in
/// a header key. Every rejection is `ConfigurationError::InvalidArgument`,
/// never a panic.
#[test]
fn test_invalid_keys_are_invalid_arguments() {
    for (key, location, expected) in [
        ("", ApiKeyLocation::Header, "must not be empty"),
        ("", ApiKeyLocation::Query, "must not be empty"),
        ("", ApiKeyLocation::Cookie, "must not be empty"),
        ("   ", ApiKeyLocation::Header, "must not be empty"),
        ("abc\r\n", ApiKeyLocation::Query, "control characters"),
        ("abc\n", ApiKeyLocation::Cookie, "control characters"),
        ("abc\rdef", ApiKeyLocation::Header, "control characters"),
        ("kéy", ApiKeyLocation::Header, "printable ASCII"),
    ] {
        match ApiKeyAuthenticator::new("https://api.example.com", "X-API-Key", key, location) {
            Err(ConfigurationError::InvalidArgument(reason)) => {
                assert!(reason.contains(expected), "{}", reason)
            }
            other => panic!(
                "expected ConfigurationError::InvalidArgument for {:?}, got {:?}",
                key, other
            ),
        }
    }
}

/// The default Debug representation must mask the stored API key: the secret
/// value must be absent and a `***` redaction marker present.
#[test]
fn test_redacts_secret() {
    let auth = ApiKeyAuthenticator::new(
        "https://api.example.com",
        "X-API-Key",
        "abc123",
        ApiKeyLocation::Header,
    )
    .unwrap();
    let debug = format!("{:?}", auth);
    assert!(!debug.contains("abc123"));
    assert!(debug.contains("***"));
}
